/**
 * Replay of the shared Noise, record and session vectors
 * (`docs/especificacao/vetores-de-teste/{noise,registros,sessoes,sessoes-ts}`).
 *
 * The first three are generated by the Rust tool; `sessoes-ts/` is generated by
 * this package (see `transcripts.test.ts`) and replayed by the Rust crate, which
 * closes the proof that the two implementations agree in both directions. With
 * every key and ephemeral fixed, each message, record and frame must match byte
 * for byte, on both sides.
 */

import { blake2s } from "@noble/hashes/blake2.js";
import { describe, expect, it } from "vitest";
import { hexEncode } from "../src/encoding.js";
import {
  ClientHandshake,
  HandshakeError,
  HandshakeKind,
  HostHandshake,
  NOISE_IK,
  NOISE_XX,
  prologue,
  type Transport,
} from "../src/session/handshake.js";
import { publicKeyFromPrivate } from "../src/session/keys.js";
import { FLAG_REKEY, RecordError, Session } from "../src/session/record.js";
import fixtureJson from "./fixtures/cacophony-xx-ik.json" with { type: "json" };
import { keypairOf, readKeys, replaySession, type SessionKeys } from "./support/session.js";
import { fromTyped, hexOf, vectorsIn, type VectorError } from "./support/vectors.js";

function blake2sHex(data: Uint8Array): string {
  return hexEncode(blake2s(data, { dkLen: 32 }));
}

// --- noise/ ---

describe("vectors: noise (cacophony)", () => {
  const files = vectorsIn("noise").filter(({ name }) => name.startsWith("noise/cacophony-"));

  it("is the vendored file, vector for vector", () => {
    expect(files.map(({ name }) => name)).toEqual(["noise/cacophony-xx-ik.json"]);
    const [file] = files;
    expect(file?.json["formato"]).toBe("noise-cacophony");
    // `noise.cacophony.test.ts` replays the fixture against the Noise code; the
    // shared file must carry the very same vectors.
    const shared = file?.json["vectors"] as unknown[];
    expect(shared.length).toBeGreaterThanOrEqual(2);
    expect(shared).toEqual(fixtureJson.vectors);
  });
});

function transportHash(transport: Transport): string {
  return hexEncode(transport.handshakeHash);
}

function expectHandshakeError(action: () => unknown, code: string): void {
  let thrown: unknown;
  try {
    action();
  } catch (error) {
    thrown = error;
  }
  expect(thrown).toBeInstanceOf(HandshakeError);
  expect((thrown as HandshakeError).code).toBe(code);
}

interface NoiseMessage {
  readonly de: string;
  readonly payload: unknown;
  readonly hex: string;
}

function replayNoise(v: Record<string, unknown>): void {
  const keys = readKeys(v["chaves"]);
  const hostId = v["host_id"] as string;
  const pattern = v["padrao"] as "XX" | "IK";
  const valid = v["valido"] === true;
  const who = v["quem_falha"] as string | null;
  const error = v["erro"] as VectorError | null;
  const qrKey = fromTyped(v["chave_do_host"]) as Uint8Array;
  const messages = v["mensagens"] as NoiseMessage[];
  const message = (index: number): { wire: Uint8Array; payload: Uint8Array } => {
    const entry = messages[index];
    if (entry === undefined) {
      throw new Error(`no message ${index}`);
    }
    return { wire: hexOf(entry.hex, "hex"), payload: fromTyped(entry.payload) as Uint8Array };
  };
  const side = (index: number, expected: string): void => {
    expect(messages[index]?.de, `message ${index}`).toBe(expected);
  };
  const same = (got: Uint8Array, index: number): void => {
    expect(hexEncode(got), `message ${index}`).toBe(hexEncode(message(index).wire));
  };

  expect(v["nome"]).toBe(pattern === "XX" ? NOISE_XX : NOISE_IK);
  expect(hexEncode(prologue(hostId))).toBe(v["prologo_hex"]);
  const hostKey = (): ReturnType<typeof keypairOf> => keypairOf(keys.hostStatic);
  const deviceKey = (): ReturnType<typeof keypairOf> => keypairOf(keys.clientStatic);
  const refused = (): string => {
    expect(valid).toBe(false);
    expect(error?.camada).toBe("handshake");
    return error?.codigo ?? "";
  };

  if (pattern === "XX") {
    // msg1: written by the client, or (a failing host) taken from the vector.
    let msg1: Uint8Array;
    let client: ClientHandshake | null = null;
    if (who === "host") {
      side(0, "cliente");
      msg1 = message(0).wire;
    } else {
      const started = ClientHandshake.pair({
        local: deviceKey(),
        hostId,
        expectedHostKey: qrKey,
        ephemeral: keys.clientEphemeral,
      });
      client = started.handshake;
      msg1 = started.msg1;
      side(0, "cliente");
      same(msg1, 0);
    }
    if (who === "host") {
      const code = refused();
      expectHandshakeError(
        () =>
          HostHandshake.respond({
            kind: HandshakeKind.pair,
            local: hostKey(),
            hostId,
            msg1,
            ephemeral: keys.hostEphemeral,
          }),
        code,
      );
      return;
    }
    const answered = HostHandshake.respond({
      kind: HandshakeKind.pair,
      local: hostKey(),
      hostId,
      msg1,
      ephemeral: keys.hostEphemeral,
    });
    side(1, "host");
    same(answered.msg2, 1);
    if (who === "cliente") {
      expectHandshakeError(() => client?.readMessage2(answered.msg2), refused());
      expect(messages).toHaveLength(2);
      return;
    }
    expect(valid).toBe(true);
    expect(client?.readMessage2(answered.msg2)).toEqual({ kind: "needs-pair-request" });
    const third = message(2);
    side(2, "cliente");
    const written = client?.writeMessage3(third.payload);
    if (written === undefined) {
      throw new Error("no client");
    }
    same(written.msg3, 2);
    const read = answered.handshake.readMessage3(written.msg3);
    expect(hexEncode(read.payload)).toBe(hexEncode(third.payload));
    expect(hexEncode(read.remoteStatic)).toBe(hexEncode(publicKeyFromPrivate(keys.clientStatic)));
    expect(transportHash(written.transport)).toBe(v["handshake_hash"]);
    expect(transportHash(read.transport)).toBe(v["handshake_hash"]);
    expect(messages).toHaveLength(3);
    return;
  }

  // IK
  if (who === "cliente" && messages.length === 0) {
    expectHandshakeError(
      () =>
        ClientHandshake.connect({
          local: deviceKey(),
          hostId,
          hostKey: qrKey,
          ephemeral: keys.clientEphemeral,
        }),
      refused(),
    );
    return;
  }
  const { handshake: client, msg1 } = ClientHandshake.connect({
    local: deviceKey(),
    hostId,
    hostKey: qrKey,
    ephemeral: keys.clientEphemeral,
  });
  side(0, "cliente");
  same(msg1, 0);
  const answered = HostHandshake.respond({
    kind: HandshakeKind.connect,
    local: hostKey(),
    hostId,
    msg1,
    ephemeral: keys.hostEphemeral,
  });
  side(1, "host");
  same(answered.msg2, 1);
  const step = client.readMessage2(answered.msg2);
  expect(valid).toBe(true);
  if (step.kind !== "established") {
    throw new Error("IK is established after msg2");
  }
  expect(hexEncode(answered.remoteStatic)).toBe(hexEncode(publicKeyFromPrivate(keys.clientStatic)));
  expect(transportHash(step.transport)).toBe(v["handshake_hash"]);
  expect(transportHash(answered.transport)).toBe(v["handshake_hash"]);
  expect(messages).toHaveLength(2);
}

describe("vectors: noise (Porecatu)", () => {
  const files = vectorsIn("noise").filter(({ name }) => !name.startsWith("noise/cacophony-"));
  it("has the vectors", () => {
    expect(files.map(({ name }) => name)).toEqual([
      "noise/ik-dh-nulo-no-cliente.json",
      "noise/ik-porecatu.json",
      "noise/xx-chave-do-qr-diferente.json",
      "noise/xx-dh-nulo-no-host.json",
      "noise/xx-porecatu.json",
    ]);
  });
  for (const { name, json } of files) {
    it(name, () => {
      replayNoise(json);
    });
  }
});

// --- registros/ ---

/** The plaintext of a record vector: byte `i` is `i mod 251`. */
function patternBytes(length: number): Uint8Array {
  const out = new Uint8Array(length);
  for (let i = 0; i < length; i++) {
    out[i] = i % 251;
  }
  return out;
}

/** An `IK` handshake with the fixed keys: `(client, host)` transports. Every call gives identical transports. */
function ikTransports(keys: SessionKeys, hostId: string): { client: Transport; host: Transport } {
  const { handshake, msg1 } = ClientHandshake.connect({
    local: keypairOf(keys.clientStatic),
    hostId,
    hostKey: publicKeyFromPrivate(keys.hostStatic),
    ephemeral: keys.clientEphemeral,
  });
  const answered = HostHandshake.respond({
    kind: HandshakeKind.connect,
    local: keypairOf(keys.hostStatic),
    hostId,
    msg1,
    ephemeral: keys.hostEphemeral,
  });
  const step = handshake.readMessage2(answered.msg2);
  if (step.kind !== "established") {
    throw new Error("IK is established after msg2");
  }
  return { client: step.transport, host: answered.transport };
}

interface RecordStep {
  readonly de: string;
  readonly now_ms: number;
  readonly texto_claro: { readonly padrao: string; readonly tamanho: number; readonly blake2s: string };
  readonly flags: number[];
  readonly registros_hex: string[] | null;
  readonly registros_blake2s: string[];
  readonly forjado: boolean;
}

function replayRecords(v: Record<string, unknown>): void {
  const keys = readKeys(v["chaves"]);
  const hostId = v["host_id"] as string;
  const politica = v["politica"] as { max_records: number; max_age_ms: number };
  const policy = { maxRecords: politica.max_records, maxAgeMs: politica.max_age_ms };
  const handshakeMs = v["handshake_ms"] as number;
  const steps = v["passos"] as RecordStep[];
  const error = v["erro"] as VectorError | null;
  expect(steps.length).toBeGreaterThan(0);

  // The two senders, a raw receiver per direction that reads the flags from the
  // ciphertext, and the record layer of each receiver.
  const senders = ikTransports(keys, hostId);
  const raws = ikTransports(keys, hostId);
  const readers = ikTransports(keys, hostId);
  const client = new Session(senders.client, { policy, nowMs: handshakeMs });
  const host = new Session(senders.host, { policy, nowMs: handshakeMs });
  const readClient = new Session(readers.client, { nowMs: handshakeMs });
  const readHost = new Session(readers.host, { nowMs: handshakeMs });

  steps.forEach((step, index) => {
    const where = `step ${index}`;
    expect(step.texto_claro.padrao).toBe("i mod 251");
    const message = patternBytes(step.texto_claro.tamanho);
    expect(blake2sHex(message), `${where}: texto_claro`).toBe(step.texto_claro.blake2s);
    const fromClient = step.de === "cliente";
    const sender = fromClient ? client : host;
    const raw = fromClient ? raws.host : raws.client;
    const reader = fromClient ? readHost : readClient;
    const stored = step.registros_hex?.map((hex) => hexOf(hex, "registros_hex"));

    if (step.forjado) {
      // Built below the record layer: only the receiver is replayed.
      expect(valid(v), where).toBe(false);
      const records = stored ?? [];
      expect(records).toHaveLength(1);
      let thrown: unknown;
      try {
        reader.open(records[0] as Uint8Array, step.now_ms);
      } catch (caught) {
        thrown = caught;
      }
      expect(thrown).toBeInstanceOf(RecordError);
      expect((thrown as RecordError).code).toBe(error?.codigo);
      return;
    }
    if (error?.codigo === "too-large" && step.registros_blake2s.length === 0) {
      let thrown: unknown;
      try {
        sender.seal(message, step.now_ms);
      } catch (caught) {
        thrown = caught;
      }
      expect(thrown).toBeInstanceOf(RecordError);
      expect((thrown as RecordError).code).toBe("too-large");
      return;
    }

    const records = sender.seal(message, step.now_ms);
    // The flags, read from the ciphertext by a receiver that knows nothing
    // about the sender.
    const flags: number[] = [];
    const rebuilt: Uint8Array[] = [];
    for (const record of records) {
      const plain = raw.decrypt(record);
      const flag = plain[0] ?? 0;
      flags.push(flag);
      rebuilt.push(plain.subarray(1));
      if ((flag & FLAG_REKEY) !== 0) {
        raw.rekeyIncoming();
      }
    }
    expect(flags, `${where}: flags`).toEqual(step.flags);
    expect(blake2sHex(concat(rebuilt)), `${where}: fragments`).toBe(step.texto_claro.blake2s);
    expect(records.map(blake2sHex), `${where}: registros_blake2s`).toEqual(step.registros_blake2s);
    if (stored !== undefined) {
      expect(records.map((record) => hexEncode(record)), `${where}: registros_hex`).toEqual(
        stored.map((record) => hexEncode(record)),
      );
    } else {
      expect(message.length, `${where}: only messages above 65 519 bytes drop their records`).toBeGreaterThan(65_519);
    }
    records.forEach((record, position) => {
      const out = reader.open(record, step.now_ms);
      if (position === records.length - 1) {
        expect(out === null ? "" : blake2sHex(out), `${where}: the message`).toBe(step.texto_claro.blake2s);
      } else {
        expect(out, `${where}: a fragment completes nothing`).toBeNull();
      }
    });
  });
}

function valid(v: Record<string, unknown>): boolean {
  return v["valido"] === true;
}

function concat(parts: readonly Uint8Array[]): Uint8Array {
  const out = new Uint8Array(parts.reduce((sum, part) => sum + part.length, 0));
  let offset = 0;
  for (const part of parts) {
    out.set(part, offset);
    offset += part.length;
  }
  return out;
}

describe("vectors: registros", () => {
  const files = vectorsIn("registros");
  it("has the vectors", () => {
    expect(files.length).toBeGreaterThanOrEqual(11);
  });
  for (const { name, json } of files) {
    it(name, () => {
      replayRecords(json);
    });
  }
});

