// --- The replays are not vacuous ---

/** Flips the last hex digit of `text`. */
function flipLastDigit(text: string): string {
  const last = text.slice(-1) === "0" ? "1" : "0";
  return text.slice(0, -1) + last;
}

/** A copy of `vector` with the value at `path` replaced by `change(value)`. */
function changed(
  vector: Record<string, unknown>,
  path: ReadonlyArray<string | number>,
  change: (value: unknown) => unknown,
): Record<string, unknown> {
  const copy = JSON.parse(JSON.stringify(vector)) as Record<string, unknown>;
  let parent = copy as Record<string | number, unknown>;
  for (const key of path.slice(0, -1)) {
    parent = parent[key] as Record<string | number, unknown>;
  }
  const last = path[path.length - 1] as string | number;
  parent[last] = change(parent[last]);
  return copy;
}

describe("vectors: a changed byte is caught", () => {
  const find = (category: string, name: string): Record<string, unknown> => {
    const file = vectorsIn(category).find((candidate) => candidate.name === `${category}/${name}`);
    if (file === undefined) {
      throw new Error(`no vector ${name}`);
    }
    return file.json;
  };
  const flip = (value: unknown): unknown => flipLastDigit(value as string);

  it("in a Noise message", () => {
    const v = changed(find("noise", "xx-porecatu.json"), ["mensagens", 1, "hex"], flip);
    expect(() => replayNoise(v)).toThrow();
  });

  it("in a record", () => {
    const v = changed(find("registros", "rekey-por-contagem.json"), ["passos", 4, "registros_hex", 0], flip);
    expect(() => replayRecords(v)).toThrow();
  });

  it("in a frame of a session", () => {
    for (const category of ["sessoes", "sessoes-ts"]) {
      const v = changed(find(category, "conexao-ik-pareado.json"), ["passos", 4, "envelope_hex", 0], flip);
      expect(() => replaySession(v), category).toThrow();
    }
  });

  it("in the clock of a rekey by age", () => {
    const v = changed(find("registros", "rekey-por-idade.json"), ["passos", 1, "now_ms"], () => 1_000);
    expect(() => replayRecords(v)).toThrow();
  });
});

describe("vectors: sessoes-ts (generated by this package)", () => {
  const files = vectorsIn("sessoes-ts");
  it("has the transcripts", () => {
    expect(files.length).toBeGreaterThanOrEqual(3);
  });
  for (const { name, json } of files) {
    it(name, () => {
      replaySession(json);
    });
  }
});
